BOUND = 1000000

def verify():
    assert BOUND == 1000000
    # exact sieve of phi and primality, integer arithmetic only
    phi = list(range(BOUND + 1))
    is_p = bytearray([1]) * (BOUND + 1)
    is_p[0] = 0
    is_p[1] = 0
    for i in range(2, BOUND + 1):
        if is_p[i]:
            j = i
            while j <= BOUND:
                is_p[j] = 0 if j > i else 1
                phi[j] -= phi[j] // i
                j += i
    assert is_p[2] == 1 and is_p[999983] == 1 and is_p[4] == 0
    assert phi[1] == 1 and phi[12] == 4 and phi[999983] == 999982
    prime_count = 0
    for v in range(2, BOUND + 1):
        if is_p[v] == 1:
            prime_count += 1
    assert prime_count == 78498
    # (i) inverted check: no m < p with (p-1) | phi(m), for any prime p <= BOUND
    for m in range(1, BOUND + 1):
        f = phi[m]
        d = 1
        while d * d <= f:
            if f % d == 0:
                for dd in (d, f // d):
                    p = dd + 1
                    if p <= BOUND and p > m and is_p[p] == 1:
                        raise AssertionError("smaller witness m=%d for n=%d" % (m, dd))
            d += 1
    # (ii) direct check: p_n = p for every prime p <= BOUND
    for p in range(2, BOUND + 1):
        if is_p[p] != 1:
            continue
        n = p - 1
        q = p
        while not (is_p[q] == 1 and q % n == 1):
            q += 1
        if q != p:
            raise AssertionError("p_n mismatch at p=%d" % p)

verify()
